/**
 * @summary Get platform statistics
 */
export const getAdminGetStatsUrl = () => {
  return `/api/admin/stats`;
};

export const adminGetStats = async (
  options?: RequestInit,
): Promise<PlatformStats> => {
  return customFetch<PlatformStats>(getAdminGetStatsUrl(), {
    ...options,
    method: "GET",
  });
};

export const getAdminGetStatsQueryKey = () => {
  return [`/api/admin/stats`] as const;
};

export const getAdminGetStatsQueryOptions = <
  TData = Awaited<ReturnType<typeof adminGetStats>>,
  TError = ErrorType<unknown>,
>(options?: {
  query?: UseQueryOptions<
    Awaited<ReturnType<typeof adminGetStats>>,
    TError,
    TData
  >;
  request?: SecondParameter<typeof customFetch>;
}) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getAdminGetStatsQueryKey();

  const queryFn: QueryFunction<Awaited<ReturnType<typeof adminGetStats>>> = ({
    signal,
  }) => adminGetStats({ signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof adminGetStats>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type AdminGetStatsQueryResult = NonNullable<
  Awaited<ReturnType<typeof adminGetStats>>
>;
export type AdminGetStatsQueryError = ErrorType<unknown>;

/**
 * @summary Get platform statistics
 */

export function useAdminGetStats<
  TData = Awaited<ReturnType<typeof adminGetStats>>,
  TError = ErrorType<unknown>,
>(options?: {
  query?: UseQueryOptions<
    Awaited<ReturnType<typeof adminGetStats>>,
    TError,
    TData
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getAdminGetStatsQueryOptions(options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}

/**
 * @summary Seed or reset demo data
 */
export const getAdminSeedDataUrl = () => {
  return `/api/admin/seed`;
};

export const adminSeedData = async (
  options?: RequestInit,
): Promise<SuccessResponse> => {
  return customFetch<SuccessResponse>(getAdminSeedDataUrl(), {
    ...options,
    method: "POST",
  });
};

export const getAdminSeedDataMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof adminSeedData>>,
    TError,
    void,
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof adminSeedData>>,
  TError,
  void,
  TContext
> => {
  const mutationKey = ["adminSeedData"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof adminSeedData>>,
    void
  > = () => {
    return adminSeedData(requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type AdminSeedDataMutationResult = NonNullable<
  Awaited<ReturnType<typeof adminSeedData>>
>;

export type AdminSeedDataMutationError = ErrorType<unknown>;

